module fixed_point_subtractor(
    parameter Q = 4,
    parameter N = 8,
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);
// Internal variables
reg signed [N-1:0] res;
// Perform subtraction based on the signs of a and b
always @(*) begin
    if(a[N-1]==b[N-1])begin
        res = {a[N-1],a[N-2:0]-b[N-2:0]};
    end else begin
        if(a[N-1]==1 && b[N-1]==0)begin
            res = a-b;
        end else begin
            res = b-a;
        end
    end

    // Handle special cases
    if(res==0)begin
        res[N-1]=0;
    end
end
// Assign the result to the output port
assign c=res;
endmodule
